package com.paymesh.backend.security.accounts;
import com.paymesh.backend.chat.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.math.*;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.sql.Timestamp;
import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
/** No authorization shortcut: invoked only under ChatEvidenceBuilder's held account lock. */
@Service
public class ChatProjectionQueries {
 private final AuthStore db;private final ObjectMapper json;private final DashboardAnalytics analytics;
 public ChatProjectionQueries(AuthStore db,ObjectMapper json,DashboardAnalytics analytics){this.db=db;this.json=json;this.analytics=analytics;}
 @Transactional(readOnly=true,propagation=Propagation.REQUIRES_NEW,isolation=Isolation.REPEATABLE_READ,timeout=5)
 public ChatEvidenceBuilder.Snapshot build(ChatEvidenceBuilder.Selection s,ChatDtos.Input input,UUID correlation){
  ObjectNode req=json.createObjectNode();req.put("correlationId",correlation.toString());req.put("callerRole",s.isAdmin()?"ADMIN":"MERCHANT");req.put("question",input.question());req.set("history",json.valueToTree(input.history()));
  ObjectNode e=req.putObject("evidence");e.put("source","JAVA_AUTHORIZED_SNAPSHOT");e.put("scope",s.isAdmin()?"ADMIN_AUTHORIZED":"MERCHANT_OWNED");e.put("collectedAt",Instant.now().truncatedTo(ChronoUnit.MICROS).toString());e.put("refundHistoryComplete",false);e.put("statisticsComplete",false);var unavailable=e.putArray("unavailableEvidence");Map<String,ChatDtos.Reference> refs=new LinkedHashMap<>();List<String> limits=new ArrayList<>();Map<String,Object> range=null;
  if(s.paymentId()!=null){var rows=db.jdbc.queryForList("SELECT payment_id,merchant_id,status,amount,currency,payment_method FROM "+db.table("payments")+" WHERE payment_id=? AND merchant_id=?",s.paymentId(),s.merchantId());if(rows.isEmpty())throw new ChatFailure(404,"CONTEXT_UNAVAILABLE","Selected context is unavailable.");var p=rows.getFirst();ObjectNode n=e.putObject("payment");n.put("ref","payment:selected");n.put("status",p.get("status").toString());n.put("amount",amount(p.get("amount"),12,true));n.put("currency",currency(p.get("currency")));n.put("paymentMethod",Set.of("UPI","CARD").contains(p.get("payment_method").toString())?p.get("payment_method").toString():"OTHER");req.put("paymentContext","payment:selected");refs.put("payment:selected",new ChatDtos.Reference("payment:selected","PAYMENT",s.paymentId().toString()));
   var refunds=db.jdbc.queryForList("SELECT refund_id,amount,status FROM "+db.table("refunds")+" WHERE payment_id=? ORDER BY refund_id LIMIT 21",s.paymentId());
   if(refunds.size()>20||refunds.stream().anyMatch(r->!"SUCCESS".equals(r.get("status")))){unavailable.add("REFUNDS");limits.add("Refund details are unavailable or exceed20; no partial refund total or remaining amount is authoritative.");}else{ArrayNode a=e.putArray("refunds");e.put("refundHistoryComplete",true);int i=0;for(var r:refunds){String ref="refund:r"+i++;var row=a.addObject();row.put("ref",ref);row.put("paymentRef","payment:selected");row.put("amount",amount(r.get("amount"),12,true));row.put("status","SUCCESS");refs.put(ref,new ChatDtos.Reference(ref,"REFUND",null));}}
   var gateways=db.jdbc.queryForList("SELECT id,gateway_name,status FROM "+db.table("payment_gateway_transactions")+" WHERE payment_id=? ORDER BY id LIMIT 21",s.paymentId());
   if(gateways.size()>20||gateways.stream().anyMatch(g->!Set.of("MOCK_RAZORPAY","MOCK_STRIPE","MOCK_ROUTER").contains(g.get("gateway_name"))||!Set.of("INITIATED","SUCCESS","FAILED","TIMEOUT","UNKNOWN").contains(g.get("status")))){unavailable.add("GATEWAYS");limits.add("Gateway detail is unavailable or exceeds20; no events or causes inferred.");}else{var a=e.putArray("gateways");int i=0;for(var g:gateways){String ref="gateway:g"+i++;var row=a.addObject();row.put("ref",ref);row.put("paymentRef","payment:selected");row.put("gatewayName",g.get("gateway_name").toString());row.put("status",g.get("status").toString());refs.put(ref,new ChatDtos.Reference(ref,"GATEWAY_TRANSACTION",null));}}
  }else unavailable.add("PAYMENT");
  if(s.linkId()!=null){var rows=db.jdbc.queryForList("SELECT status,amount,currency,payment_method,expires_at FROM "+db.table("payment_links")+" WHERE link_id=? AND merchant_id=?",s.linkId(),s.merchantId());if(rows.isEmpty())throw new ChatFailure(404,"CONTEXT_UNAVAILABLE","Selected context is unavailable.");var l=rows.getFirst();String state=l.get("status").toString();var a=db.jdbc.queryForList("SELECT status FROM "+db.table("checkout_attempts")+" WHERE link_id=? ORDER BY CASE WHEN status='FAILED' THEN 1 ELSE 0 END,created_at DESC,attempt_id DESC LIMIT 1",s.linkId());String attempt=a.isEmpty()?"":a.getFirst().get("status").toString();
   if(state.equals("ACTIVE")){if(Set.of("PROCESSING","UNCERTAIN").contains(attempt))state=attempt;else if(!((Timestamp)l.get("expires_at")).toInstant().isAfter(Instant.now()))state="EXPIRED";else if(attempt.equals("FAILED"))state="FAILED";}
   var c=e.putObject("checkout");c.put("ref","checkout:selected");c.put("status",state);c.put("amount",amount(l.get("amount"),12,true));c.put("currency",currency(l.get("currency")));c.put("paymentMethod",l.get("payment_method").toString());if(s.paymentId()!=null&&Set.of("PAID","PROCESSING","UNCERTAIN","FAILED").contains(state))c.put("paymentRef","payment:selected");refs.put("checkout:selected",new ChatDtos.Reference("checkout:selected","PAYMENT_LINK",s.linkId().toString()));
  }else unavailable.add("CHECKOUT");
  if(s.statistics()!=null){Map<String,String> filter=new LinkedHashMap<>();var st=s.statistics();if(st.from()!=null)filter.put("from",st.from());if(st.to()!=null)filter.put("to",st.to());if(st.currency()!=null)filter.put("currency",st.currency());var r=analytics.range(filter,s.isAdmin());range=Map.of("from",r.from().toString(),"to",r.to().toString(),"timezone","UTC","endExclusive",true);List<Object> args=new ArrayList<>(List.of(Timestamp.from(r.from()),Timestamp.from(r.to())));String scope="";if(!s.merchantId().isEmpty()){scope+=" AND p.merchant_id=?";args.add(s.merchantId());}if(!r.currency().isEmpty()){scope+=" AND p.currency=?";args.add(r.currency());}else scope+=" AND p.currency IN ('INR','USD')";
   ArrayNode a=e.putArray("statistics");int index=0;for(String kind:List.of("PAYMENT","REFUND")){String col=kind.equals("PAYMENT")?"p":"f",source=db.table("payments")+" p"+(kind.equals("REFUND")?" JOIN "+db.table("refunds")+" f ON f.payment_id=p.payment_id":"");var rows=db.jdbc.queryForList("SELECT p.currency,"+col+".status,count(*) AS count,sum("+col+".amount) AS amount FROM "+source+" WHERE "+col+".created_at>=? AND "+col+".created_at<?"+scope+" GROUP BY p.currency,"+col+".status ORDER BY p.currency,"+col+".status",args.toArray());
    for(var row:rows){if(index>=24)throw unsupported();long count=((Number)row.get("count")).longValue();if(count>1_000_000_000L)throw unsupported();String ref="statistics:s"+index++;var n=a.addObject();n.put("ref",ref);n.put("kind",kind);n.put("currency",currency(row.get("currency")));n.put("status",row.get("status").toString());n.put("count",count);n.put("amount",amount(row.get("amount"),24,false));refs.put(ref,new ChatDtos.Reference(ref,"STATISTICS",null));}
   }e.put("statisticsComplete",true);var currencies=e.putArray("statisticsCurrencies");if(r.currency().isEmpty()){currencies.add("INR");currencies.add("USD");}else currencies.add(r.currency());limits.add("Statistics cover only the declared INR/USD scope and UTC window; daily/method breakdowns are not represented by the Python schema.");
  }else unavailable.add("STATISTICS");
  return new ChatEvidenceBuilder.Snapshot(req,Collections.unmodifiableMap(refs),List.copyOf(limits),range,s);
 }
 private String currency(Object o){if(!Set.of("INR","USD").contains(o.toString()))throw unsupported();return o.toString();}
 private String amount(Object o,int digits,boolean positive){try{BigDecimal n=((BigDecimal)o).setScale(2,RoundingMode.UNNECESSARY);if(n.signum()<0||positive&&n.signum()==0||n.precision()-n.scale()>digits)throw unsupported();return n.toPlainString();}catch(RuntimeException ex){throw unsupported();}}
 private ChatFailure unsupported(){return new ChatFailure(422,"UNSUPPORTED_EVIDENCE","Authorized evidence exceeds the supported chat projection.");}
}
